package com.shopsphere.controller;
import com.shopsphere.model.User; import com.shopsphere.util.DB; import jakarta.servlet.*; import jakarta.servlet.http.*; import jakarta.servlet.annotation.*; import java.io.IOException; import java.sql.*; import java.math.BigDecimal;
@WebServlet("/checkout") public class CheckoutServlet extends HttpServlet {
 protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{q.getRequestDispatcher("/WEB-INF/views/checkout.jsp").forward(q,p);}
 protected void doPost(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{User u=(User)q.getSession().getAttribute("user");String address=String.join(", ",safe(q.getParameter("address")),safe(q.getParameter("city")),safe(q.getParameter("state")),safe(q.getParameter("pincode")));if(address.replace(", ","").isBlank()){q.setAttribute("error","Please complete your delivery address.");doGet(q,p);return;}try(Connection c=DB.getConnection()){c.setAutoCommit(false);try{BigDecimal total=BigDecimal.ZERO;java.util.List<Object[]> lines=new java.util.ArrayList<>();String query="SELECT p.product_id,p.name,p.price,p.discount,p.stock,c.quantity FROM cart c JOIN products p ON p.product_id=c.product_id WHERE c.user_id=? AND p.status=TRUE FOR UPDATE";try(PreparedStatement s=c.prepareStatement(query)){s.setLong(1,u.getUserId());try(ResultSet r=s.executeQuery()){while(r.next()){int qty=r.getInt("quantity");if(qty>r.getInt("stock"))throw new IllegalArgumentException("Stock changed for "+r.getString("name")+". Update your cart.");BigDecimal price=r.getBigDecimal("price").multiply(BigDecimal.ONE.subtract(r.getBigDecimal("discount").divide(new BigDecimal("100")))).setScale(2,java.math.RoundingMode.HALF_UP);total=total.add(price.multiply(BigDecimal.valueOf(qty)));lines.add(new Object[]{r.getLong("product_id"),r.getString("name"),price,qty});}}}if(lines.isEmpty())throw new IllegalArgumentException("Your cart is empty.");long orderId;try(PreparedStatement s=c.prepareStatement("INSERT INTO orders(user_id,address_text,total_amount,payment_method,payment_status,order_status) VALUES(?,?,?,'MOCK','SUCCESS','PLACED')",Statement.RETURN_GENERATED_KEYS)){s.setLong(1,u.getUserId());s.setString(2,address);s.setBigDecimal(3,total);s.executeUpdate();try(ResultSet r=s.getGeneratedKeys()){r.next();orderId=r.getLong(1);}}for(Object[] line:lines){try(PreparedStatement s=c.prepareStatement("INSERT INTO order_items(order_id,product_id,product_name,quantity,price) VALUES(?,?,?,?,?)")){s.setLong(1,orderId);s.setLong(2,(Long)line[0]);s.setString(3,(String)line[1]);s.setInt(4,(Integer)line[3]);s.setBigDecimal(5,(BigDecimal)line[2]);s.executeUpdate();}try(PreparedStatement s=c.prepareStatement("UPDATE products SET stock=stock-? WHERE product_id=? AND stock>=?")){s.setInt(1,(Integer)line[3]);s.setLong(2,(Long)line[0]);s.setInt(3,(Integer)line[3]);if(s.executeUpdate()!=1)throw new IllegalArgumentException("Stock changed. Please retry checkout.");}}try(PreparedStatement s=c.prepareStatement("INSERT INTO payments(order_id,payment_method,transaction_reference,amount,payment_status) VALUES(?,'MOCK',?,?, 'SUCCESS')")){s.setLong(1,orderId);s.setString(2,"MOCK-"+System.currentTimeMillis());s.setBigDecimal(3,total);s.executeUpdate();}try(PreparedStatement s=c.prepareStatement("DELETE FROM cart WHERE user_id=?")){s.setLong(1,u.getUserId());s.executeUpdate();}c.commit();p.sendRedirect(q.getContextPath()+"/orders?placed="+orderId);}catch(Exception e){c.rollback();if(e instanceof IllegalArgumentException){q.setAttribute("error",e.getMessage());q.getRequestDispatcher("/WEB-INF/views/checkout.jsp").forward(q,p);}else throw new ServletException("Checkout transaction failed",e);}finally{c.setAutoCommit(true);}}catch(Exception e){throw new ServletException("Checkout failed",e);}}
 private String safe(String x){return x==null?"":x.trim().replaceAll("[<>]","");}
}
